function parseDocument(content: string): ParsedSection[] {
  const lines = content.split("\n")
  const sections: ParsedSection[] = []

  let currentSection: ParsedSection | null = null
  let currentContent: string[] = []
  let orderIndex = 0

  // Skip to first real section (after table of contents)
  let foundFirstSection = false

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]

    // Pattern 1: # 1 Introduction (standard main section)
    const mainSectionMatch = line.match(/^# (\d+)\s+(.+)$/)
    if (mainSectionMatch) {
      // Save previous section
      if (currentSection) {
        currentSection.content = currentContent.join("\n").trim()
        if (currentSection.content) {
          sections.push(currentSection)
        }
      }

      foundFirstSection = true
      orderIndex++
      currentSection = {
        section_number: mainSectionMatch[1],
        section_title: mainSectionMatch[2],
        parent_section: null,
        content: "",
        order_index: orderIndex,
      }
      currentContent = [line]
      continue
    }

    // Pattern 2: # Section 6: Title or # Section 12: Title
    const sectionLabelMatch = line.match(/^# Section (\d+):\s*(.+)$/)
    if (sectionLabelMatch) {
      // Save previous section
      if (currentSection) {
        currentSection.content = currentContent.join("\n").trim()
        if (currentSection.content) {
          sections.push(currentSection)
        }
      }

      foundFirstSection = true
      orderIndex++
      currentSection = {
        section_number: sectionLabelMatch[1],
        section_title: sectionLabelMatch[2],
        parent_section: null,
        content: "",
        order_index: orderIndex,
      }
      currentContent = [line]
      continue
    }

    // Pattern 3: # 7. Reports & Metrics (number with period)
    const periodSectionMatch = line.match(/^# (\d+)\.\s+(.+)$/)
    if (periodSectionMatch) {
      // Save previous section
      if (currentSection) {
        currentSection.content = currentContent.join("\n").trim()
        if (currentSection.content) {
          sections.push(currentSection)
        }
      }

      foundFirstSection = true
      orderIndex++
      currentSection = {
        section_number: periodSectionMatch[1],
        section_title: periodSectionMatch[2],
        parent_section: null,
        content: "",
        order_index: orderIndex,
      }
      currentContent = [line]
      continue
    }

    // Pattern 4: # 5.2 Title (subsection using single #)
    const singleHashSubMatch = line.match(/^# (\d+)\.(\d+)\s+(.+)$/)
    if (singleHashSubMatch && foundFirstSection) {
      // Save previous section
      if (currentSection) {
        currentSection.content = currentContent.join("\n").trim()
        if (currentSection.content) {
          sections.push(currentSection)
        }
      }

      orderIndex++
      const parentNum = singleHashSubMatch[1]
      const subNum = singleHashSubMatch[2]
      currentSection = {
        section_number: `${parentNum}.${subNum}`,
        section_title: singleHashSubMatch[3],
        parent_section: parentNum,
        content: "",
        order_index: orderIndex,
      }
      currentContent = [line]
      continue
    }

    // Pattern 5: ## 5.1 Title or ## 8.1 Title (standard subsection)
    const subSectionMatch = line.match(/^## (\d+)\.(\d+)\s+(.+)$/)
    if (subSectionMatch && foundFirstSection) {
      // Save previous section
      if (currentSection) {
        currentSection.content = currentContent.join("\n").trim()
        if (currentSection.content) {
          sections.push(currentSection)
        }
      }

      orderIndex++
      const parentNum = subSectionMatch[1]
      const subNum = subSectionMatch[2]
      currentSection = {
        section_number: `${parentNum}.${subNum}`,
        section_title: subSectionMatch[3],
        parent_section: parentNum,
        content: "",
        order_index: orderIndex,
      }
      currentContent = [line]
      continue
    }

    // Add line to current section content
    if (currentSection && foundFirstSection) {
      currentContent.push(line)
    }
  }

  // Save last section
  if (currentSection) {
    currentSection.content = currentContent.join("\n").trim()
    if (currentSection.content) {
      sections.push(currentSection)
    }
  }

  return sections
}

