async function seedDocument(
  supabase: ReturnType<typeof createClient>,
  config: DocumentConfig,
  sections: ParsedSection[]
): Promise<void> {
  console.log(`\n🚀 Seeding document: ${config.title}`)

  // Ensure document exists and get its ID
  const documentId = await ensureDocument(supabase, config)

  // Clear existing sections for this document only
  const { error: deleteError } = await supabase
    .from("document_sections")
    .delete()
    .eq("document_id", documentId)

  if (deleteError) {
    console.error("❌ Error clearing existing sections:", deleteError.message)
    process.exit(1)
  }

  console.log(`   Cleared existing sections for document`)

  // Insert new sections with document_id
  const sectionsToInsert = sections.map((section) => ({
    document_id: documentId,
    section_number: section.section_number,
    section_title: section.section_title,
    parent_section: section.parent_section,
    original_content: section.content,
    current_content: section.content,
    content_hash: generateHash(section.content),
    status: "pending",
    order_index: section.order_index,
    version: 1,
  }))

  const { data, error: insertError } = await supabase
    .from("document_sections")
    .insert(sectionsToInsert)
    .select()

  if (insertError) {
    console.error("❌ Error inserting sections:", insertError.message)
    process.exit(1)
  }

  console.log(`   ✅ Inserted ${data?.length || 0} sections`)
}

