async function main(): Promise<void> {
  console.log("🔍 MTS Multi-Document Seeding Script")
  console.log("=".repeat(80))

  // Parse CLI arguments
  const args = process.argv.slice(2)
  const isPreview = args.includes("--preview")
  const isAll = args.includes("--all")

  // Get specific document slug
  const docArg = args.find((arg) => arg.startsWith("--document="))
  const targetSlug = docArg ? docArg.split("=")[1] : null

  if (!isAll && !targetSlug) {
    console.log("\nUsage:")
    console.log("  npx tsx scripts/seed-document.ts --document=<slug>")
    console.log("  npx tsx scripts/seed-document.ts --all")
    console.log("  npx tsx scripts/seed-document.ts --document=<slug> --preview")
    console.log("\nAvailable documents:")
    DOCUMENTS.forEach((doc) => {
      console.log(`  - ${doc.slug}: ${doc.title}`)
    })
    process.exit(0)
  }

  // Determine which documents to seed
  const documentsToSeed = isAll
    ? DOCUMENTS
    : DOCUMENTS.filter((d) => d.slug === targetSlug)

  if (documentsToSeed.length === 0) {
    console.error(`\n❌ Error: Document "${targetSlug}" not found in configuration`)
    console.log("\nAvailable documents:")
    DOCUMENTS.forEach((doc) => {
      console.log(`  - ${doc.slug}: ${doc.title}`)
    })
    process.exit(1)
  }

  // Setup Supabase client (only if not preview)
  let supabase: ReturnType<typeof createClient> | null = null
  if (!isPreview) {
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
    const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY

    if (!supabaseUrl || !serviceRoleKey) {
      console.error("\n❌ Error: Missing Supabase credentials")
      console.error("   Please set NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY in .env.local")
      process.exit(1)
    }

    supabase = createClient(supabaseUrl, serviceRoleKey)
  }

  // Process each document
  for (const docConfig of documentsToSeed) {
    const documentPath = path.join(__dirname, "..", docConfig.sourceFile)

    // Check if document file exists
    if (!fs.existsSync(documentPath)) {
      console.warn(`\n⚠️ Warning: Source file not found: ${documentPath}`)
      console.warn(`   Skipping document: ${docConfig.slug}`)
      continue
    }

    console.log(`\n📁 Reading: ${docConfig.sourceFile}`)

    // Read and parse document
    const content = fs.readFileSync(documentPath, "utf-8")
    console.log(`   Document size: ${(content.length / 1024).toFixed(1)} KB`)

    const sections = parseDocument(content)
    console.log(`   Found ${sections.length} sections`)

    if (isPreview) {
      previewSections(sections, docConfig)
    } else if (supabase) {
      await seedDocument(supabase, docConfig, sections)
    }
  }

  if (isPreview) {
    console.log("\n💡 Run without --preview to seed to Supabase")
  } else {
    console.log("\n✅ Seeding complete!")
  }
}

