async function seedUsers(): Promise<void> {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
  const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY

  if (!supabaseUrl || !serviceRoleKey) {
    console.error("\n❌ Error: Missing Supabase credentials")
    console.error("   Please set NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY in .env.local")
    process.exit(1)
  }

  const supabase = createClient(supabaseUrl, serviceRoleKey, {
    auth: {
      autoRefreshToken: false,
      persistSession: false,
    },
  })

  console.log("🔍 MTS User Seeding Script")
  console.log("=" .repeat(80))
  console.log(`\n📝 Seeding ${testUsers.length} test users...\n`)

  let created = 0
  let skipped = 0
  let failed = 0

  for (const user of testUsers) {
    try {
      // Create user in Supabase Auth
      const { data, error } = await supabase.auth.admin.createUser({
        email: user.email,
        password: user.password,
        email_confirm: true, // Auto-confirm email for testing
        user_metadata: {
          full_name: user.name,
        },
      })

      if (error) {
        if (error.message.includes("already been registered")) {
          console.log(`   ⏭️  ${user.email} - Already exists, skipping`)
          skipped++
        } else {
          console.log(`   ❌ ${user.email} - Error: ${error.message}`)
          failed++
        }
        continue
      }

      // Update profile with organization
      if (data.user) {
        await supabase
          .from("profiles")
          .update({
            full_name: user.name,
            organization: "DynPro",
            role: "reviewer",
          })
          .eq("id", data.user.id)
      }

      console.log(`   ✅ ${user.email} - Created successfully`)
      created++
    } catch (err) {
      console.log(`   ❌ ${user.email} - Error: ${err instanceof Error ? err.message : "Unknown error"}`)
      failed++
    }
  }

  console.log("\n" + "=" .repeat(80))
  console.log(`\n📊 Summary:`)
  console.log(`   Created: ${created}`)
  console.log(`   Skipped: ${skipped}`)
  console.log(`   Failed:  ${failed}`)
  console.log(`   Total:   ${testUsers.length}`)

  if (created > 0) {
    console.log("\n✅ User seeding complete!")
    console.log("\n📋 Test credentials:")
    console.log("-" .repeat(60))
    for (const user of testUsers) {
      console.log(`   ${user.email} / ${user.password}`)
    }
  }
}

