export async function getCommentsByDocument(
  supabase: Client,
  documentId: string
): Promise<CommentWithSectionAndAuthor[]> {
  // First get all sections for this document
  const { data: sections, error: sectionsError } = await supabase
    .from("document_sections")
    .select("id, section_number, section_title, order_index")
    .eq("document_id", documentId)

  if (sectionsError || !sections || sections.length === 0) {
    console.error("Error fetching sections:", sectionsError)
    return []
  }

  // Build a map of section info for quick lookup
  const sectionMap = new Map(
    sections.map((s) => [
      s.id,
      {
        section_id: s.id,
        section_number: s.section_number,
        section_title: s.section_title,
        order_index: s.order_index,
      },
    ])
  )

  const sectionIds = sections.map((s) => s.id)

  // Fetch all comments for these sections with author profiles
  const { data: comments, error: commentsError } = await supabase
    .from("comments")
    .select(`
      *,
      author:profiles!comments_author_id_fkey(*)
    `)
    .in("section_id", sectionIds)
    .order("created_at", { ascending: false })

  if (commentsError) {
    console.error("Error fetching comments:", commentsError)
    return []
  }

  // Merge section info into each comment
  const commentsWithSection: CommentWithSectionAndAuthor[] = (comments || []).map((comment) => ({
    ...comment,
    section: sectionMap.get(comment.section_id)!,
  })) as CommentWithSectionAndAuthor[]

  return commentsWithSection
}

