export async function getLeaderboard(
  supabase: Client,
  type: "weekly" | "all_time" = "weekly",
  limit: number = 10
): Promise<LeaderboardEntry[]> {
  const orderColumn = type === "weekly" ? "weekly_points" : "total_points"

  const { data, error } = await supabase
    .from("user_stats")
    .select(`
      user_id,
      total_points,
      weekly_points,
      comments_added,
      edits_accepted,
      profiles!inner(full_name, avatar_url, organization)
    `)
    .gt(orderColumn, 0)
    .order(orderColumn, { ascending: false })
    .limit(limit)

  if (error) {
    console.error("Error fetching leaderboard:", error)
    return []
  }

  // Get achievement counts for each user
  const userIds = (data || []).map((d) => d.user_id)
  const { data: achievementCounts } = await supabase
    .from("user_achievements")
    .select("user_id")
    .in("user_id", userIds)

  const countMap = new Map<string, number>()
  achievementCounts?.forEach((a) => {
    countMap.set(a.user_id, (countMap.get(a.user_id) || 0) + 1)
  })

  // Type for the joined profile data
  type ProfileData = { full_name: string | null; avatar_url: string | null; organization: string | null }

  return (data || []).map((entry) => {
    // Supabase returns profiles as single object with !inner join, cast through unknown
    const profile = entry.profiles as unknown as ProfileData | null
    return {
      user_id: entry.user_id,
      full_name: profile?.full_name ?? null,
      avatar_url: profile?.avatar_url ?? null,
      organization: profile?.organization ?? null,
      total_points: entry.total_points,
      weekly_points: entry.weekly_points,
      comments_added: entry.comments_added,
      edits_accepted: entry.edits_accepted,
      achievement_count: countMap.get(entry.user_id) || 0,
    }
  }) as LeaderboardEntry[]
}

