export async function checkAndAwardAchievements(
  supabase: Client,
  userId: string
): Promise<Achievement[]> {
  const newAchievements: Achievement[] = []

  // Get user stats
  const stats = await getUserStats(supabase, userId)
  if (!stats) return []

  // Get all achievements
  const allAchievements = await getAllAchievements(supabase)

  // Get user's current achievements
  const { data: earnedAchievements } = await supabase
    .from("user_achievements")
    .select("achievement_id")
    .eq("user_id", userId)

  const earnedIds = new Set((earnedAchievements || []).map((a) => a.achievement_id))

  // Check each achievement
  for (const achievement of allAchievements) {
    if (earnedIds.has(achievement.id)) continue

    const currentValue = stats[achievement.requirement_field as keyof UserStats] as number
    if (currentValue >= achievement.requirement_value) {
      // Award the achievement
      const { error } = await supabase.from("user_achievements").insert({
        user_id: userId,
        achievement_id: achievement.id,
        notified: false,
      })

      if (!error) {
        newAchievements.push(achievement)

        // Award bonus points
        if (achievement.points_reward > 0) {
          const { data: currentStats } = await supabase
            .from("user_stats")
            .select("total_points, weekly_points")
            .eq("user_id", userId)
            .single()

          if (currentStats) {
            await supabase
              .from("user_stats")
              .update({
                total_points: currentStats.total_points + achievement.points_reward,
                weekly_points: currentStats.weekly_points + achievement.points_reward,
              })
              .eq("user_id", userId)

            // Record achievement bonus transaction
            await supabase.from("point_transactions").insert({
              user_id: userId,
              points: achievement.points_reward,
              action_type: "achievement_earned",
              description: `Earned: ${achievement.name}`,
            })
          }
        }
      }
    }
  }

  return newAchievements
}

