chunk_60.text:
export async function getAllDocumentsWithStats(
  supabase: Client
): Promise<DocumentWithStats[]> {
  // Query 1: Get all documents
  const { data: documents, error: docError } = await supabase
    .from("documents")
    .select("*")
    .order("created_at", { ascending: true })

  if (docError || !documents?.length) {
    console.error("Error fetching documents:", docError)
    return []
  }

  const documentIds = documents.map((d) => d.id)

  // Query 2: Get all section stats grouped by document
  // Returns: { document_id, total_sections, approved_sections }
  const { data: sectionStats } = await supabase
    .from("document_sections")
    .select("document_id, status")
    .in("document_id", documentIds)

  // Query 3: Get all comments grouped by document (via sections)
  const { data: allSections } = await supabase
    .from("document_sections")
    .select("id, document_id")
    .in("document_id", documentIds)

  const sectionToDocMap = new Map<string, string>()
  const docSectionIds = new Map<string, string[]>()

  allSections?.forEach((s) => {
    sectionToDocMap.set(s.id, s.document_id)
    const existing = docSectionIds.get(s.document_id) || []
    existing.push(s.id)
    docSectionIds.set(s.document_id, existing)
  })

  const allSectionIds = allSections?.map((s) => s.id) || []

  // Query 4 & 5: Get comments and edits counts in parallel
  const [{ data: allComments }, { data: allEdits }] = await Promise.all([
    allSectionIds.length > 0
      ? supabase
          .from("comments")
          .select("section_id")
          .in("section_id", allSectionIds)
      : Promise.resolve({ data: [] }),
    allSectionIds.length > 0
      ? supabase
          .from("edits")
          .select("section_id")
          .in("section_id", allSectionIds)
      : Promise.resolve({ data: [] }),
  ])

  // Aggregate stats by document
  const statsMap = new Map<string, {
    sections_count: number
    approved_count: number
    comments_count: number
    edits_count: number
  }>()

  // Initialize stats for all documents
  documentIds.forEach((id) => {
    statsMap.set(id, {
      sections_count: 0,
      approved_count: 0,
      comments_count: 0,
      edits_count: 0,
    })
  })

  // Count sections and approved sections
  sectionStats?.forEach((s) => {
    const stats = statsMap.get(s.document_id)
    if (stats) {
      stats.sections_count++
      if (s.status === "approved") {
        stats.approved_count++
      }
    }
  })

  // Count comments by document
  allComments?.forEach((c) => {
    const docId = sectionToDocMap.get(c.section_id)
    if (docId) {
      const stats = statsMap.get(docId)
      if (stats) stats.comments_count++
    }
  })

  // Count edits by document
  allEdits?.forEach((e) => {
    const docId = sectionToDocMap.get(e.section_id)
    if (docId) {
      const stats = statsMap.get(docId)
      if (stats) stats.edits_count++
    }
  })

  // Combine documents with their stats
  return documents.map((doc) => {
    const stats = statsMap.get(doc.id) || {
      sections_count: 0,
      approved_count: 0,
      comments_count: 0,
      edits_count: 0,
    }
    const progressPercentage = stats.sections_count > 0
      ? Math.round((stats.approved_count / stats.sections_count) * 100)
      : 0

    return {
      ...doc,
      ...stats,
      progress_percentage: progressPercentage,
    } as DocumentWithStats
  })
}

