export async function updateSectionContent(
  supabase: Client,
  sectionId: string,
  newContent: string
): Promise<DocumentSection | null> {
  // First get current version
  const { data: currentSection, error: fetchError } = await supabase
    .from("document_sections")
    .select("version")
    .eq("id", sectionId)
    .single()

  if (fetchError) {
    console.error("Error fetching section version:", fetchError)
    throw fetchError
  }

  const newVersion = (currentSection?.version || 1) + 1

  // Update content and version
  const { data, error } = await supabase
    .from("document_sections")
    .update({
      current_content: newContent,
      version: newVersion,
      updated_at: new Date().toISOString(),
    })
    .eq("id", sectionId)
    .select()
    .single()

  if (error) {
    console.error("Error updating section content:", error)
    throw error
  }

  return data as DocumentSection
}

